  str_quest_base_dayli_tips_awards_got = "Recomp. retiradas",
  str_quest_base_story_new_chapter_open = "Nova Missão de Capítulo disponível",
  str_quest_base_daily_reset_tips = "Missão Diária reiniciada",
  str_quest_base_awards_info_look = "Prévia",
  str_quest_base_story_chapter_index = "Capítulo %s",
  str_quest_base_story_all_chapter_clean = "Todas as Mis. de Cap. concluídas!",
  str_quest_base_story_current_chapter_clean = "Todas as Mis. desse Capítulo foram concluídas",
  str_quest_base_story_click_lock_chapter = "Conclua missões na Trama anterior p/ desb.",
  str_quest_base_desc_101 = "Soroz, este é o início de sua jornada. Ganhos inesperados, mudanças, lições e crescimento... O fortalecimento é sempre seguido de angústia. Se não puder escapar, abrace-o. Seu sofrimento não será em vão.\n—Bethlehem",
  str_quest_base_desc_102 = "Chegar ao mundo é uma experiência profunda, não é? Espero que você lide com as crises de forma calma e racional, valorizando seus laços. Todos e tudo o que você vê fazem parte do Astral e, no final, se tornarão parte da Aurora, até mesmo uma parte de você... Aceite, entenda, responda e continue crescendo.\n—Bethlehem",
  str_quest_base_desc_103 = "Ecos do passado reverberam novamente, com a chegada de conterrâneos, inimigos e companheiros de luta. Prepare-se para o pior, mas espere o melhor. Pondere seu ódio pessoal contra a missão do seu novo grupo. Tais lições só serão aprendidas com sangue e lágrimas.\n—Bethlehem",
  str_quest_base_desc_104 = "Agora, você entende seu objetivo? Sente uma identificação com pessoas de fora do seu grupo? À frente está a última cidade dos Aurorians, uma ilha flutuante no céu. Lá, você encontrará novos laços e dará um passo mais firme rumo à jornada para superar a escuridão.\n—Bethlehem",
  str_quest_base_desc_105 = "Constantemente frustrado, mas sempre lutando, como uma fera que nunca sabe recuar, como um homem corajoso que empunhou sua espada, mas morreu em uma terra esquecida. O passado continuará avançando, trazendo você cara a cara com seus maiores medos. Olhe para o rosto dela e me diga: Quem você vê?\n—Bethlehem",
  str_quest_base_desc_106 = "Ansioso? Como a Aurora sugere, você está próximo do fundo, um charco de amargura e ressentimento, uma prisão de ferro construída de fracassos e humilhação. Mas é apenas aqui que você encontrará a verdadeira força - não aço e ferro, mas uma visão ampla e uma mente inclusiva.\n—Bethlehem",
  str_quest_base_desc_107 = "Finalmente estamos entrando em uma nova fase da nossa conversa interespacial, Celestita. Você nunca entenderia meu papel, assim como eu não entenderia fragmentos de palavras escritas em vagos augúrios. A Aurora está escurecendo, e homens desesperados preenchem o céu de Lumópolis com suas asas abertas. Você conquista ou é conquistado. Esse é o fim da história.\n—Bethlehem",
  str_quest_base_desc_108 = "Mesmo no abismo mais profundo e escuro, você sobreviverá para ver o cumprimento da profecia. É nisso que acredito, e minha intuição insiste que eu siga. Aproveite a oportunidade, celestita, e condene o negro a voltar para onde ele pertence!\n—Bethlehem",
  str_quest_base_desc_109 = "Temos duas casas: a que fica sob seus pés e a que fica no coração. Os afortunados descobrirão que não há diferença entre elas. No entanto, a maioria das almas deve suportar um conflito constante entre ambas, e pode até ficar sem esperança de mais uma vez colocar os pés na terra no fundo de suas memórias. Mesmo que o coração não queira continuar, não há outra maneira.\n                                                                                                                       —Bethlehem",
  str_quest_base_desc_110 = "Acredito que esta terra permitirá que você cresça, te lembrando de muitas coisas e, ao mesmo tempo, permitindo que faça as pazes com elas com calma. O fim de sua jornada está à frente. Deixe para trás o ressentimento e o ódio. Espero que na próxima vez que nos encontrarmos você esteja diferente.\n                                                                                                                       —Bethlehem",
  str_quest_base_desc_111 = "A noite eterna, o território do qual nenhum auroriano quer estar perto, é um abismo erodido pela escuridão. Neste Interlúdio do Crepúsculo, aproveite a oportunidade fugaz, mestre do Colosso, para romper a escuridão. Que seu desejo seja realizado.\n\n-- Belém",
  str_quest_base_desc_112 = "A esperança é frequentemente acompanhada de provações, como uma flor coberta de espinhos. Se você está preparado para ser ferido e machucado, volte para onde começou. Buscar, perder, desesperar-se e, finalmente, erguer a cabeça mais uma vez.\n\n—Bethlehem",
  str_quest_base_desc_113 = "A lâmina da verdade perfura o peito de alguém, rasgando em pedaços o coração frágil por dentro. \"Como isso pode ser?\" \"Não pode ser!\" Choque, dúvida, ressentimento e, em seguida, olhando para o vazio ao lado do abismo perdido. Não consigo ver sua escolha, Caelestita, não consigo ver nada.\n\n——Bethlehem",
  str_quest_base_desc_114 = "Todo mundo está constantemente buscando conhecimento em sua vida. Você é afortunado, mas também lamentável. O destino deu a você mais espaço para explorar. Você pode ir mais longe do que a maioria das pessoas, mas é uma jornada solitária. Não sei onde você vai parar, porque seu destino está além do que posso ver.\n—Belém",
  str_quest_base_desc_115 = "Você notou que está começando a conhecer mais e mais pessoas? Eles têm origens e destinos diferentes, mas seus caminhos coincidem com os seus em um determinado momento. Tantas pessoas vivem sob o céu. Os sortudos com o sol acima de suas cabeças são banhados pela luz solar mais abundante, mas aqueles que ficam no crepúsculo são os mais distantes do sol.\n—Belém",
  str_quest_base_desc_116 = "Que reviravolta irônica do destino é essa que te obriga a ficar junto com um velho inimigo. Se um mar de chamas ou um poço profundo está à frente, não há escolha a não ser enfrentá-lo com seus amigos.\n—Bethlehem",
  str_quest_base_desc_117 = "O campo de batalha é um palco para conspiradores, e espectadores ignorantes vêm de todas as direções para ele. A noite sem limites se aproxima, mas os aurorianos ainda não acordaram de seus doces sonhos.\n—Bethlehem",
  str_quest_base_desc_118 = "No meio das mudanças de poder, aqueles ignorados pelo destino sobem ao palco mundial sob o olhar de muitos. No entanto, a ambição se mostra a arma mais inútil no campo de batalha: apenas ao derrotar seu antigo eu é que se pode escapar do redemoinho da política e obter uma vida renovada.\n—Bethlehem",
  str_quest_base_desc_119 = "A força vem da autopropulsão ou da concessão dos outros? Até que você testemunhe formas poderosas lutando na lama, cavando suas próprias covas, você finalmente perceberá que a fragilidade é a essência da vida.\n—Bethlehem",
  str_quest_base_desc_120 = "Uma existência estrangeira finalmente fez contato com Illumina após mais de 600 anos. Devemos virar as páginas dos livros de história em busca de possibilidades, ou devemos abandonar o passado e forjar um novo caminho? Essa é a questão em mãos, bem como um enigma que tem perturbado inúmeras gerações de Aurorians.\n—Bethlehem",
  str_quest_base_desc_121 = "Você passou incontáveis horas de felicidade com seus amigos, mas nunca imaginou que o momento de dizer adeus chegaria tão repentinamente. O sinal do passado retornou. Desta vez, você deve se tornar forte e explorar seu passado nas ruínas desconhecidas.\n—Bethlehem",
  str_quest_base_desc_122 = "\"Para erguer faróis ao longo do caminho à frente\", assim falei eu, o Queen do Norte.\n—Bethlehem",
  str_quest_base_type_stroy_with_space = "História",
