  str_quest_base_achieve_type_407_space = "Colossus",
  str_quest_base_achieve_finish_list_title = "Missões Concluídas",
  str_quest_base_desc_123 = "Você agora testemunhou a noite eterna—você solidificou a resolução em seu coração? Inúmeras almas estão presas em um impasse de sombras, perseguindo uma esperança fugaz. Mas para você, essa esperança é real.\nVocê vai agarrá-la, pois esta história começa com seus primeiros passos como um herói. Você deve guardar essa centelha de esperança e, em troca, ela persistirá por causa de você. Acredite nisso e avance com fé inabalável.\n—Bethlehem",
